quote_work_items_name_shape.value:
(
        "equipment"."quote_work_items"."department" is null and "equipment"."quote_work_items"."name" is not null and length(trim("equipment"."quote_work_items"."name")) > 0
      ) or (
        "equipment"."quote_work_items"."department" is not null and "equipment"."quote_work_items"."name" is null
      )

quote_kind_shape.value:
(
        "equipment"."quote"."kind" = 'product' and "equipment"."quote"."product_id" is not null and "equipment"."quote"."work_title" is null
      ) or (
        "equipment"."quote"."kind" = 'custom' and "equipment"."quote"."product_id" is null and "equipment"."quote"."product_unit_id" is null and "equipment"."quote"."work_title" is not null and length(trim("equipment"."quote"."work_title")) > 0 and "equipment"."quote"."quoted_base_price" = 0
      )
